/**
 * 0055 — the automated email catalog (M-04). One entry per email the studio sends on its own, with default copy in
 * ES / EN, its trigger, who receives it and when it must exist. The source is Lore's three inventories of
 * 2026-10-02 (website, customer app, teacher app — `docs/reference/automated-emails.md`); the website and the
 * customer app share one account, so their emails are one set and an entry lists every inventory row it answers.
 *
 * The seed writes one `email_templates` row per entry; M-04 offers to recreate any entry whose row was deleted.
 * Nothing here sends: the automation runner (Supabase) emits the trigger and renders the row, not this file.
 */
import type { Bi } from '../specs/types';
import { tenant } from '../tenant/tenant';

/** Who receives it: a member or prospect, a teacher, or the studio team. */
export type EmailAudience = 'customer' | 'teacher' | 'studio';
/** When it has to exist: before launch, in the first 60 days, or later. */
export type EmailPriority = 'launch' | 'first_60' | 'later';
/** What the 2026-10-02 inventory said about it. */
export type EmailIntake = 'sending' | 'designed' | 'whatsapp_only' | 'whatsapp_off' | 'not_designed' | 'missing';
/**
 * Which preference gates it. `account` and `team` always send (security, legal, money owed, work); the others follow
 * the member's `notification_prefs` row for the email channel; `marketing` needs an explicit opt-in.
 */
export type EmailCategory = 'account' | 'bookings' | 'waitlist' | 'payments' | 'events' | 'marketing' | 'team';

export const EMAIL_AUDIENCES: EmailAudience[] = ['customer', 'teacher', 'studio'];
export const EMAIL_PRIORITIES: EmailPriority[] = ['launch', 'first_60', 'later'];

export interface EmailCatalogEntry {
  key: string;
  name: Bi;
  audience: EmailAudience;
  trigger: string;
  sendsWhen: Bi;
  priority: EmailPriority;
  intake: EmailIntake;
  category: EmailCategory;
  /** Inventory rows it answers: `web-e3` = website, existing #3; `app-m1` = customer app, missing #1; `tea-m7` = teacher app. */
  refs: string[];
  /** A screen already tells the person this email will arrive. */
  promised?: boolean;
  /** Email or WhatsApp is still to be decided (every teacher message, per the teacher inventory). */
  channelTbd?: boolean;
  subject: Bi;
  body: Bi;
  cta?: { label: Bi; href: string };
}

/** Deep-link scheme of the apps (`hoyapp://` for the HOY tenant); teacher links live under `teach/`. */
export const APP = `${tenant.slug}app://`;

type Meta = Pick<EmailCatalogEntry, 'priority' | 'intake' | 'category' | 'refs'> & { promised?: boolean; channelTbd?: boolean };
const e = (key: string, audience: EmailAudience, name: Bi, trigger: string, sendsWhen: Bi, meta: Meta, subject: Bi, body: Bi, cta?: EmailCatalogEntry['cta']): EmailCatalogEntry =>
  ({ key, audience, name, trigger, sendsWhen, ...meta, subject, body, cta });
const cta = (es: string, en: string, href: string) => ({ label: { es, en }, href });
const teach = (meta: Omit<Meta, 'category' | 'channelTbd'>): Meta => ({ ...meta, category: 'team', channelTbd: true });

